// Interaction and presentation refinements for the frontend prototype.
const iconPaths={home:'M3 10.5 12 3l9 7.5M5 9v11h5v-7h4v7h5V9',shop:'M4 8h16l1 13H3L4 8Zm4 0V6a4 4 0 0 1 8 0v2',cards:'M8 3h12v16H8zM4 7v14h12M11 7h6M11 10h6',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21a8 8 0 0 1 16 0',scan:'M8 3H3v5M16 3h5v5M21 16v5h-5M8 21H3v-5M7 7h3v3H7zM14 7h3v3h-3zM7 14h3v3H7zM14 14h3v3h-3z',spark:'m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6L12 2Z',diamond:'m3 8 4-5h10l4 5-9 13L3 8Zm0 0h18M7 3l5 18 5-18',crown:'m3 6 5 5 4-8 4 8 5-5-2 14H5L3 6Z',arrow:'M5 12h14m-5-5 5 5-5 5',check:'m5 12 4 4 10-10'};
function uiIcon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]?`<path d="${iconPaths[name]}"/>`:''}</svg>`}
const scrollPositions={};let modalOrigin=null,returnIntent=null,selectedRecipe={id:0,target:2};
function go(p){if(busy)return;const same=p===page;scrollPositions[page]=window.scrollY;page=p;closeModal();render();history.pushState({page:p},'', '#'+p);window.scrollTo(0,same?0:scrollPositions[p]||0)}
window.addEventListener('popstate',e=>{if(busy)return;page=e.state?.page||'home';closeModal();render();window.scrollTo(0,scrollPositions[page]||0)});
function closeModal(){if(busy)return;$('#overlay').innerHTML='';$('#app').inert=false;document.body.style.overflow='';modalOrigin?.isConnected&&modalOrigin.focus({preventScroll:true});modalOrigin=null}
function modal(title,body){if(!$('#overlay').children.length)modalOrigin=document.activeElement;$('#overlay').innerHTML=`<div class="modalback" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><span class="sheet-grip" aria-hidden="true"></span><div class="modalhead"><div><div class="eyebrow">COLLECTION ATELIER</div><h2>${title}</h2></div><button class="close" onclick="closeModal()" aria-label="关闭">×</button></div>${body}</section></div>`;$('#app').inert=true;document.body.style.overflow='hidden';requestAnimationFrame(()=>$('.modal .close')?.focus({preventScroll:true}))}
document.addEventListener('keydown',e=>{const m=$('.modal');if(!m||e.key!=='Tab')return;const els=[...m.querySelectorAll('button:not([disabled]),input,select,a[href]')].filter(el=>el.getClientRects().length);let first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
function title(en,cn,desc){return `<div class="pagetitle"><div><div class="eyebrow">${en}</div><h1>${cn}</h1><p>${desc}</p></div><span class="demo"><i></i> 交互预览</span></div>`}
function success(title,desc,next='collection',label='查看我的收藏'){if(page==='draw'&&title.includes('积分')){next='draw';label='返回抽奖页面'}render();modal(title,`<div class="success"><div class="check">${uiIcon('check')}</div><h3>${title}</h3><p>${desc}</p></div><div class="sheet-actions"><button class="primary" onclick="go('${next}')">${label} ${uiIcon('arrow')}</button><button class="secondary" onclick="closeModal()">继续浏览</button></div>`)}
function balance(){return `<section class="balance"><div class="balance-top"><span class="eyebrow">MY COLLECTION POINTS</span><button class="balance-level" onclick="go('member')">${uiIcon('crown')} Lv.${state.level} ${levels[state.level]} →</button></div><div class="balance-main"><div><div class="number">${fmt(state.points)}<small>可用积分</small></div><button class="balance-link" onclick="go('points')">收支明细 →</button></div><button class="scan" onclick="scan()">${uiIcon('scan')}<span>扫码领积分</span></button></div><div class="balance-note">${state.level===3?'全部收藏权益已解锁':`下一等级解锁${state.level===0?'二星 / 三星合成':state.level===1?'点券兑换':'四星 / 五星合成'}<button onclick="go('member')">${fmt(costs[state.level+1])} 积分升级 →</button>`}</div></section>`}
function card(t,star=1,qty=null){const eligible=qty!==null&&qty>=3&&star<5&&state.level<(star+1<4?1:3)?'等级待解锁':qty!==null&&qty>=3&&star<5?'可合成升星':null;return `<article class="toycard"><button class="card-hit" onclick="${qty===null?'product('+t.id+')':'assetDetail('+t.id+','+star+')'}" aria-label="${t.name} ${star}星 ${qty===null?fmt(t.price)+'积分':'持有'+qty+'张'}"><div class="art" style="--tone:${t.tone}"><span class="artlabel">${t.en}</span>${art(t)}<span class="cardcrest">✦</span><span class="serial">HERO COLLECTION / 0${t.id+1}</span></div><div class="cardinfo"><div class="card-name"><strong>${t.name}</strong><span class="stars" aria-label="${star}星">${'✦'.repeat(star)}</span></div><div class="cardmeta"><span>${t.series}</span><span class="price">${qty===null?fmt(t.price)+' <small>积分</small>':'× '+qty}</span></div></div></button>${eligible?`<button class="card-ready" onclick="synth(${t.id},${star+1})">${uiIcon('spark')}${eligible} ${uiIcon('arrow')}</button>`:''}</article>`}
function home(){let ht=toys[heroChoice];return title('THE HONOR COLLECTION','热爱，值得珍藏。','王者皮肤灵感，凝成你的英雄收藏。')+`<div class="homegrid"><section class="hero hero-${heroChoice}"><div class="hero-copy"><span class="pill">王者万象棋形象 · 主题收藏</span><div class="hero-kicker">THE ART OF COLLECTING</div><h2>本命入藏，<br>星光为你。</h2><p>从一张心动，到一整个英雄图鉴。<br>扫码积攒积分，开启你的收藏旅程。</p><button class="primary" onclick="product(${heroChoice})">收藏 ${ht.name} ${uiIcon('arrow')}</button></div><div class="heroart">${art(ht)}</div><div class="hero-sign"><span>0${heroChoice+1} / 04</span>${ht.en}<small>${ht.series} · 概念卡面</small></div><div class="hero-switch" aria-label="切换英雄主题">${toys.map((t,i)=>`<button class="${i===heroChoice?'on':''}" aria-pressed="${i===heroChoice}" onclick="setHero(${i})" aria-label="切换至${t.name}"><span style="background:${t.tone}"></span>${t.name}</button>`).join('')}</div><span class="hero-orbit" aria-hidden="true">✧</span></section>${balance()}</div><div class="quick">${[['spark','幸运抽奖','100 积分 / 次',"go('draw')"],['diamond','点券兑换',state.level<2?'Lv.2 解锁':'已解锁',"shopTab='tickets';go('shop')"],['cards','卡牌合成',state.assets.some(a=>a.qty>=3&&a.star<5)?'有材料可升星':'点亮下一颗星','openSynth()'],['crown','会员权益','收藏成长计划',"go('member')"]].map(([i,t,s,action])=>`<button onclick="${action}"><span class="qicon">${uiIcon(i)}</span><span><strong>${t}</strong><small>${s}</small></span></button>`).join('')}</div><div class="lowergrid"><section><div class="sectiontitle"><div><span class="eyebrow">CURATED HEROES</span><h2>为你甄选</h2></div><button class="textbtn" onclick="go('shop')">全部卡牌 ${uiIcon('arrow')}</button></div><div class="cards">${toys.slice(0,3).map(t=>card(t)).join('')}</div></section><section><div class="sectiontitle"><div><span class="eyebrow">THE COLLECTOR'S CIRCLE</span><h2>收藏家俱乐部</h2></div></div><div class="club"><div class="eyebrow">MEMBERSHIP / LV.0${state.level}</div><h3>你的下一次心动，<br>还有更多可能。</h3><p>合成升星 · 点券兑换 · 逐级解锁</p><button onclick="go('member')">探索会员权益 ${uiIcon('arrow')}</button><span class="badgeart">${uiIcon('crown')}</span></div></section></div><div class="notice"><b>概念预览</b><span>卡面主题、积分与权益为演示配置，最终以确认后的授权素材与业务规则为准。</span><button class="textbtn" onclick="rules()">了解详情 →</button></div>`}
function setHero(n){const y=window.scrollY;heroChoice=n;render();window.scrollTo(0,y)}
function collection(){let a=state.assets.filter(a=>a.qty>0&&(!starFilter||a.star===starFilter)),total=state.assets.reduce((s,a)=>s+a.qty,0),unique=new Set(state.assets.filter(a=>a.qty>0).map(a=>a.id)).size,ready=state.assets.filter(a=>a.qty>=3&&a.star<5&&state.level>=(a.star<3?1:3)).length;return title('YOUR HERO GALLERY','我的英雄图鉴','每一颗星，都有你的收藏故事。')+`<div class="gallery-overview"><div><strong>${unique}<small> / ${toys.length}</small></strong><span>已收集英雄</span></div><div><strong>${total}</strong><span>卡牌总数</span></div><button onclick="openSynth()"><span>${uiIcon('spark')}</span><strong>${ready?ready+' 组可升星':'合成工坊'}</strong><small>查看材料与配方 →</small></button></div><div class="filterbar star-filters">${[0,1,2,3,4,5].map(n=>`<button class="${starFilter===n?'selected':''}" aria-pressed="${starFilter===n}" onclick="starFilter=${n};render()">${n?n+' 星':'全部'}</button>`).join('')}</div>${a.length?`<div class="shopcards">${a.map(a=>card(toys[a.id],a.star,a.qty)).join('')}</div>`:`<div class="empty">${uiIcon('cards')}<h3>下一颗星，等你点亮</h3><p>还没有${starFilter?starFilter+' 星':''}卡牌，去探索喜欢的英雄吧。</p><button class="primary" onclick="go('shop')">探索卡牌</button></div>`}`}
function compactHero(t,star=1){return `<div class="detail-hero"><div class="art" style="--tone:${t.tone}">${art(t)}</div><div><span class="eyebrow">${t.en}</span><h3>${t.name}</h3><div class="stars">${'✦'.repeat(star)}</div><p>${t.series}<br>王者万象棋形象卡牌</p></div></div>`}
function showProduct(id){let t=toys[id];modal('收藏 '+t.name,`${compactHero(t)}<div class="detail-facts"><span>${t.motif}</span><span>测试库存 ${t.stock} 张 · 单次最多 10 张</span></div><div class="qty"><label>收藏数量</label><div><button aria-label="减少数量" onclick="adjustQty(${id},-1)">−</button><strong id="qty-value">${productQty}</strong><button aria-label="增加数量" onclick="adjustQty(${id},1)">＋</button></div></div><div id="purchase-summary"></div><div class="sheet-actions"><button class="primary" id="buy-action" onclick="buy(${id})"></button><span class="action-note">明确卡牌购买 · 确认后加入演示收藏</span></div>`);updatePurchase(id)}
function adjustQty(id,delta){productQty=Math.max(1,Math.min(10,toys[id].stock,productQty+delta));$('#qty-value').textContent=productQty;updatePurchase(id)}
function updatePurchase(id){let n=toys[id].price*productQty,short=n>state.points;$('#purchase-summary').innerHTML=summary([['本次获得',toys[id].name+' · 1 星 × '+productQty],['消耗积分',fmt(n)],['当前可用',fmt(state.points)],['购买后余额',short?'还差 '+fmt(n-state.points)+' 积分':fmt(state.points-n)+' 积分']]);$('#buy-action').innerHTML=(short?'去扫码补充积分':'确认收藏 · '+fmt(n)+' 积分')+uiIcon('arrow');$('#buy-action').onclick=()=>short?scan(()=>showProduct(id)):buy(id)}
function assetDetail(id,star){let a=state.assets.find(a=>a.id===id&&a.star===star),t=toys[id];modal(t.name+' · '+star+' 星',`${compactHero(t,star)}${summary([['当前持有',a.qty+' 张'],['收藏系列',t.series]])}${star<5?`<p class="helper">3 张同名同星卡牌，可确定合成 1 张 ${star+1} 星卡牌。</p><div class="sheet-actions"><button class="primary" onclick="synth(${id},${star+1})">查看升星配方 ${uiIcon('arrow')}</button></div>`:'<p class="helper">已达到最高星级，珍藏你的五星光芒。</p>'}`)}
function openSynth(){if(!login('openSynth()'))return;let a=state.assets.find(a=>a.qty>=3&&a.star<5&&state.level>=(a.star<3?1:3))||state.assets.find(a=>a.qty>0&&a.star<5);synth(a?.id||0,a?a.star+1:2)}
function synth(id,target){if(!login('openSynth()'))return;selectedRecipe={id,target};let t=toys[id],required=target<4?1:3,qty=state.assets.find(a=>a.id===id&&a.star===target-1)?.qty||0,levelOk=state.level>=required;modal('合成工坊',`<div class="recipe-selects"><div><label for="synthtoy">目标英雄</label><select id="synthtoy" onchange="synth(Number(this.value),selectedRecipe.target)">${toys.map(t=>`<option value="${t.id}" ${t.id===id?'selected':''}>${t.name}</option>`).join('')}</select></div><div><label for="synthstar">目标星级</label><select id="synthstar" onchange="synth(selectedRecipe.id,Number(this.value))">${[2,3,4,5].map(n=>`<option value="${n}" ${n===target?'selected':''}>${n} 星 · Lv.${n<4?1:3}</option>`).join('')}</select></div></div><div class="recipe-visual"><div>${compactHero(t,target-1)}<small>材料 × 3</small></div><span class="recipe-arrow">${uiIcon('arrow')}</span><div>${compactHero(t,target)}<small>产出 × 1</small></div></div><div class="material-meter"><span>${t.name} ${target-1} 星材料</span><strong>${qty} / 3 张</strong></div><div class="material-track"><i style="width:${Math.min(100,qty/3*100)}%"></i></div><p class="helper">${qty>=3?'材料充足，合成后剩余 '+(qty-3)+' 张材料。':'还缺 '+(3-qty)+' 张同名同星卡牌。'}<br>确定成功 · 无附加积分 · 测试配方</p>${!levelOk?`<div class="inline-warning">${uiIcon('crown')} ${target} 星合成需 Lv.${required} ${levels[required]}</div>`:''}<div class="sheet-actions">${!levelOk?`<button class="primary" onclick="returnIntent=()=>synth(${id},${target});go('member')">升级以解锁 ${uiIcon('arrow')}</button>`:qty<3?`<button class="primary" ${target>2?'disabled':''} onclick="product(${id})">${target===2?'补充材料 · 收藏 '+t.name:'请先合成 '+(target-1)+' 星材料'}</button>`:`<button class="primary" onclick="confirmSynth(${id},${target})">消耗 3 张材料 · 确认合成</button>`}</div>`)}
function confirmSynth(id,target){if(busy)return;let a=state.assets.find(a=>a.id===id&&a.star===target-1);if(!a||a.qty<3||state.level<(target<4?1:3))return;busy=true;$('.sheet-actions .primary').disabled=true;$('.sheet-actions .primary').innerHTML='<span class="spinner"></span> 正在合成';setTimeout(()=>{a.qty-=3;addAsset(id,target,1);record('合成',toys[id].name+'合成至 '+target+' 星',0,'消耗 '+(target-1)+' 星 ×3，获得 '+target+' 星 ×1');busy=false;success('升星成功',toys[id].name+' · '+target+' 星已加入收藏。','collection','查看升星卡牌')},650)}
function member(){let next=state.level+1;return `<button class="back" onclick="go('profile')">← 返回我的</button>`+title('THE COLLECTOR’S CIRCLE','让热爱，进阶。','等级永久保留，权益随你逐级解锁。')+`<div class="member-feature"><div class="member-emblem">${uiIcon('crown')}</div><div><span class="eyebrow">YOUR MEMBERSHIP</span><h2>Lv.${state.level} ${levels[state.level]}</h2><p>已解锁：抽奖 · 卡牌购买${state.level>=1?' · 二星 / 三星合成':''}${state.level>=2?' · 点券兑换':''}${state.level>=3?' · 四星 / 五星合成':''}</p></div>${next<=3?`<button class="primary" onclick="upgrade()">解锁${levels[next]} · ${fmt(costs[next])} 积分 ${uiIcon('arrow')}</button>`:'<span class="status">已达到最高等级</span>'}</div><div class="sectiontitle" style="margin-top:30px"><h2>会员权益一览</h2><span class="helper">高等级继承全部已有权益</span></div><div class="membergrid">${levels.map((l,i)=>`<section class="tier ${state.level===i?'current':''}"><div class="eyebrow">LEVEL 0${i}</div><h3>${l}</h3><span class="status">${i===state.level?'当前等级':i<state.level?'已达成':i===next?'下一等级':'待解锁'}</span><div class="tiercost">${i?fmt(costs[i]):'免费'} <small>${i?'逐级升级积分':'基础等级'}</small></div><p>${['积分抽奖<br>卡牌购买','继承基础权益<br>二星 / 三星卡牌合成','继承进阶权益<br>王者荣耀点券兑换','继承全部权益<br>四星 / 五星卡牌合成'][i]}</p></section>`).join('')}</div><p class="helper">等级、费用、权限与有效期均为演示配置，正式规则待确认。</p>`}
function confirmUpgrade(target){if(target!==state.level+1||!enough(costs[target]))return;state.points-=costs[target];state.level=target;record('升级','升级至 '+levels[target],-costs[target],'Lv.'+(target-1)+' → Lv.'+target);if(returnIntent){render();modal('升级成功',`<div class="success"><div class="check">${uiIcon('check')}</div><h3>新的权益已解锁</h3><p>已成为 ${levels[target]}，可以继续刚才的操作。</p></div><div class="sheet-actions"><button class="primary" onclick="resumeIntent()">继续刚才的操作 ${uiIcon('arrow')}</button><button class="secondary" onclick="closeModal()">稍后再去</button></div>`)}else success('升级成功','欢迎成为'+levels[target]+'，新的权益已解锁。','member','查看已解锁权益')}
function resumeIntent(){let fn=returnIntent;returnIntent=null;closeModal();fn?.()}
let scanResume=null;function scan(resume=null){if(!login('scan()'))return;scanResume=resume;modal('扫码领积分',`<div class="scanframe"><span></span>${uiIcon('scan')}<small>将 CD 领取码置于框内</small></div><p class="helper">每件 CD 的专属码仅可领取一次。此处为模拟扫码，不调用摄像头。</p><div class="sheet-actions"><button class="primary" onclick="claim('valid')">模拟领取 +500 积分 ${uiIcon('arrow')}</button></div><details class="demo-tools"><summary>体验其他扫码结果</summary><div class="scanoptions"><button onclick="claim('used')">已领取</button><button onclick="claim('expired')">过期码</button><button onclick="claim('invalid')">无效码</button><button onclick="claim('network')">网络异常</button></div></details>`)}
const previousClaim=claim;claim=function(type){if(type==='valid'&&!state.claimed){state.claimed=true;state.points+=500;record('扫码','CD 扫码领取',500,'鹿灵心语 · 演示唯一领取码');if(scanResume){render();modal('领取成功',`<div class="success"><div class="check">${uiIcon('check')}</div><h3>+500 积分</h3><p>当前余额 ${fmt(state.points)} 积分，可以返回刚才的收藏。</p></div><div class="sheet-actions"><button class="primary" onclick="resumeScan()">继续刚才的收藏 ${uiIcon('arrow')}</button></div>`)}else success('+500 积分','领取成功！当前可用 '+fmt(state.points)+' 积分。','shop','去收藏喜欢的英雄');return}previousClaim(type)};
function resumeScan(){let f=scanResume;scanResume=null;f?.()}
function drawConfirm(){if(!login('drawConfirm()')||!enough(100))return;drawRun()}
const previousDraw=draw;draw=function(){let html=previousDraw();html=html.replace('onclick="drawConfirm()">开启惊喜<small>100 积分 / 次</small>','onclick="drawConfirm()">抽一次<small>消耗 100 积分</small>');html=html.replace(' · 测试奖池</p>',' · 抽后余额 '+fmt(Math.max(0,state.points-100))+' 积分</p>');return html};
function exchange(i){if(!login('exchange('+i+')'))return;if(state.level<2){returnIntent=()=>exchange(i);locked(2,'点券兑换');return}const n=[600,2800,6000][i];if(!enough(n))return;modal('兑换 '+[60,300,680][i]+' 点券',`<div class="exchange-head"><span>${uiIcon('diamond')}</span><div><strong>${[60,300,680][i]} <small>点券</small></strong><p>王者荣耀 · 演示兑换</p></div></div><div class="recipe-selects"><div><label for="server">游戏区服</label><select id="server" onchange="updateExchange(${i})"><option>微信 · iOS</option><option>微信 · Android</option><option>QQ · iOS</option><option>QQ · Android</option></select></div><div><label for="account">游戏账号标识</label><input id="account" placeholder="请输入演示账号" maxlength="40" oninput="updateExchange(${i})" aria-describedby="account-error"></div></div><p id="account-error" class="field-error" role="alert"></p><div id="exchange-summary"></div><label class="confirm-check"><input id="confirm-account" type="checkbox"><span>我已核对区服和账号标识，确认兑换资料正确。</span></label><div class="sheet-actions"><button class="primary" onclick="exchangeConfirm(${i})">确认兑换 · ${fmt(n)} 积分</button><span class="action-note">无需账号密码 · 前端模拟，不发放真实点券</span></div>`);updateExchange(i)}
function updateExchange(i){const n=[600,2800,6000][i];$('#account-error').textContent='';$('#account').removeAttribute('aria-invalid');$('#confirm-account').checked=false;$('#exchange-summary').innerHTML=summary([['游戏区服',escapeHTML($('#server').value)],['账号标识',escapeHTML($('#account').value.trim())||'请填写上方账号'],['消耗积分',fmt(n)],['兑换后余额',fmt(state.points-n)+' 积分'],['处理时间','1–3 个工作日（待确认）']])}
function exchangeConfirm(i){let account=$('#account').value.trim();if(account.length<3){$('#account-error').textContent='请填写至少 3 个字符的演示账号标识';$('#account').setAttribute('aria-invalid','true');$('#account').focus();return}if(!$('#confirm-account').checked){$('#account-error').textContent='请先核对并勾选兑换资料确认';$('#confirm-account').focus();return}pendingExchange={i,server:$('#server').value,account};exchangeSubmit()}
function orderDetail(id){let r=state.records.find(r=>r.id===id);if(!r)return;const statuses=['待处理','处理中','已完成'],at=statuses.indexOf(r.status);modal('兑换进度',`<div class="order-status"><span class="status">${r.status}</span><h3>${r.title}</h3><p>${r.status==='已关闭并退款'?'积分已退回账户':r.status==='人工核查'?'我们正在核查发放结果，请保留订单编号。':'预计 1–3 个工作日处理（测试配置）'}</p></div><div class="order-timeline">${statuses.map((s,i)=>`<div class="${i<=at?'done':''}"><span>${i<at?'✓':i+1}</span><small>${s}</small></div>`).join('')}</div>${summary([['订单编号',r.id],['兑换资料',escapeHTML(r.desc)],['积分费用',fmt(-r.delta)]])}<div class="sheet-actions"><button class="secondary" onclick="support()">联系俱乐部客服</button></div><details class="demo-tools"><summary>体验订单状态</summary><div class="scanoptions">${['待处理','处理中','已完成','人工核查'].map(s=>`<button ${['已关闭并退款','已完成'].includes(r.status)?'disabled':''} onclick="orderState('${id}','${s}')">${s}</button>`).join('')}<button ${['已关闭并退款','已完成'].includes(r.status)?'disabled':''} onclick="refund('${id}')">关闭并退款</button></div></details>`)}

function render(){const active=['home','shop','collection','profile'].includes(page)?page:['member','points','records'].includes(page)?'profile':'home';$('#app').innerHTML=`<header><button class="brand" onclick="go('home')" aria-label="荣耀藏馆首页"><i>${uiIcon('spark')}</i><div>荣耀藏馆<small>THE HONOR COLLECTION</small></div></button><nav class="topnav">${[['home','首页'],['shop','商城'],['collection','图鉴'],['profile','我的']].map(([p,n])=>`<button class="${p===active?'active':''}" ${p===active?'aria-current="page"':''} onclick="go('${p}')">${n}</button>`).join('')}</nav><button class="userchip textbtn" onclick="go('profile')" aria-label="我的账户"><div class="avatar">${uiIcon('user')}</div><span>${state.logged?'峡谷收藏家':'游客 · 登录'}</span></button></header><main class="view view-${page}">${({home,shop,collection,member,profile,records,points:()=>records(true),draw})[page]()}</main><footer><span>荣耀藏馆 / THE HONOR COLLECTION</span><button class="textbtn" onclick="rules()">前端概念预览 · 测试配置</button></footer><nav class="bottomnav" aria-label="主导航">${[['home','home','首页'],['shop','shop','商城'],['collection','cards','图鉴'],['profile','user','我的']].map(([p,i,n])=>`<button class="${p===active?'active':''}" ${p===active?'aria-current="page"':''} onclick="go('${p}')"><span>${uiIcon(i)}</span>${n}</button>`).join('')}</nav>`}
// Keep user-entered prototype text inert in records.
const originalRecord=record;record=function(type,title,delta,desc,status='已完成'){originalRecord(type,title,delta,desc,status);state.records[0].id='DEMO-'+Date.now().toString().slice(-8)+'-'+state.records.length};
const beforeRefinedDrawRun=drawRun;drawRun=function(){if(busy)return;beforeRefinedDrawRun();if(busy){const button=$('.drawcenter');if(button){button.disabled=true;button.innerHTML='<span class="spinner"></span><small>正在开启惊喜</small>'}}};
const routePages=['home','shop','collection','profile','member','records','points','draw'];
if(routePages.includes(location.hash.slice(1)))page=location.hash.slice(1);
history.replaceState({page},'',location.hash||'#'+page);
render();
